select (select id from public.objectives where code = 'K3-C4-L3-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالتحليل الكهربائي؟', null, '["استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي","استعمال تفاعل كيميائي تلقائي لإنتاج طاقة كهربائية","تفكيك المركبات بالحرارة إلى عناصرها","ذوبان المركب الأيوني في الماء إلى أيوناته"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 2, 'ما المقصود بخلية التحليل الكهربائي؟', null, '["الخلية الكهروكيميائية التي تولد تيارًا من تفاعل تلقائي","الخلية التي يحترق فيها الوقود لإنتاج الكهرباء","الخلية الكهروكيميائية التي يحدث فيها تحليل كهربائي","الوعاء الذي تُصهر فيه الفلزات بالحرارة فقط"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 3, 'أيّ الأمثلة الآتية يمثل خلية تحليل كهربائي؟', null, '["بطارية جافة في أثناء تشغيل مصباح يدوي","خلية خارصين–نحاس في أثناء إضاءة مصباح","خلية وقود في أثناء احتراق الهيدروجين فيها","بطارية ثانوية في أثناء إعادة شحنها"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 4, 'أيّ العمليات الآتية تُعد تحليلًا كهربائيًا؟', null, '["احتراق الهيدروجين بالأكسجين في خلية الوقود","تفريغ بطارية السيارة في أثناء تشغيل المحرك","تفكيك الماء إلى H₂ وO₂ بتمرير تيار كهربائي","ذوبان كلوريد الصوديوم في الماء"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'متوسط', 'الكتاب ص 155 — تطبيقات التحليل الكهربائي'),
('mcq', 5, 'ما نوع التفاعل الذي يحدث في خلية التحليل الكهربائي؟', null, '["تفاعل أكسدة واختزال تلقائي","تفاعل أكسدة واختزال غير تلقائي","تفاعل تعادل بين حمض وقاعدة","تفاعل ترسيب لمادة صلبة"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 154 و158 — التحليل الكهربائي والخلاصة'),
('mcq', 6, 'ما المكوّن الذي يلزم وجوده في خلية التحليل الكهربائي ولا يلزم في الخلية الجلفانية؟', null, '["قنطرة ملحية بين نصفي الخلية","قطبان من فلزين مختلفين","مصباح كهربائي في الدائرة","مصدر طاقة كهربائية خارجي"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'متوسط', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('mcq', 7, 'أيّ المجموعات الآتية تضم خلايا تحليل كهربائي فقط؟', null, '["خلية داون، وخلية هول–هيروليت، وخلية الطلاء بالفضة","خلية داون، وخلية الوقود، وخلية الطلاء بالفضة","خلية خارصين–نحاس، وخلية داون، وخلية هول–هيروليت","البطارية الجافة، وخلية الوقود، وخلية خارصين–نحاس"]'::jsonb, 'تطبيق', 'تصنيف أمثلة', 'صعب', 'الكتاب ص 154–158 — التحليل الكهربائي وتطبيقاته'),
('essay', 1, 'عرّف كلًّا من: التحليل الكهربائي، وخلية التحليل الكهربائي، ثم اذكر مثالين على خلايا تحليل كهربائي.', null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 154 — عكس تفاعلات الأكسدة والاختزال'),
('essay', 2, 'عرّف التحليل الكهربائي، واربطه بتلقائية تفاعل الأكسدة والاختزال، موضحًا لماذا تحتاج خلية التحليل إلى مصدر طاقة خارجي.', null, null, 'فهم', 'تعريف وربط', 'متوسط', 'الكتاب ص 154 و158 — التحليل الكهربائي والتقويم 4-3 (السؤال 22)'),
('essay', 3, 'صنّف كل عملية مما يأتي إلى تحليل كهربائي أو غير ذلك، مع تعليل مختصر لكل منها مستندًا إلى تعريف التحليل الكهربائي: (أ) إنتاج الألومنيوم بطريقة هول–هيروليت. (ب) إضاءة مصباح بخلية خارصين–نحاس. (ج) طلاء ملعقة بالفضة. (د) تشغيل سيارة بخلية وقود هيدروجينية.', null, null, 'تطبيق', 'تصنيف مع تعليل', 'متوسط', 'الكتاب ص 154–158 — التحليل الكهربائي وتطبيقاته')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
