insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'يعرّف الكتاب التحليل الكهربائي بأنه استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي.', '["","هذا وصف عمل الخلية الجلفانية لا التحليل الكهربائي.","التفكك بالحرارة تحلل حراري لا يستعمل الطاقة الكهربائية.","هذا وصف لعملية التفكك الأيوني في الماء، ولا يحدث فيه تفاعل أكسدة واختزال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T11:23:22.582Z"}'::jsonb),
('mcq', 2, 2, 'خلية التحليل الكهربائي هي الخلية الكهروكيميائية التي يحدث فيها تحليل كهربائي، أي تُستعمل فيها الطاقة الكهربائية لإحداث تفاعل كيميائي.', '["هذا وصف الخلية الجلفانية لا خلية التحليل الكهربائي.","هذا وصف خلية الوقود، وهي نوع من الخلايا الجلفانية.","","الصهر بالحرارة لا يستعمل الطاقة الكهربائية لإحداث تفاعل أكسدة واختزال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T11:23:22.582Z"}'::jsonb),
('mcq', 3, 3, 'عند إعادة شحن بطارية ثانوية فإنها تعمل عمل خلية تحليل كهربائي؛ لأن الطاقة الكهربائية تُستعمل لإحداث التفاعل غير التلقائي.', '["البطارية في أثناء التشغيل تولد التيار من تفاعل تلقائي، فهي خلية جلفانية.","هذه خلية جلفانية؛ يحدث فيها تفاعل تلقائي يزود المصباح بالكهرباء.","خلية الوقود تنتج طاقة كهربائية من تفاعل تلقائي، فهي ليست خلية تحليل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.582Z"}'::jsonb),
('mcq', 4, 2, 'تحليل الماء بالتيار الكهربائي (2H₂O → 2H₂ + O₂) يستعمل الطاقة الكهربائية لإحداث تفاعل كيميائي، فهو تحليل كهربائي.', '["هذا تفاعل تلقائي ينتج طاقة كهربائية، وهو عكس التحليل الكهربائي للماء.","تفريغ البطارية تفاعل تلقائي يحول الطاقة الكيميائية إلى كهربائية.","","الذوبان لا يستعمل طاقة كهربائية ولا يحدث فيه تفاعل أكسدة واختزال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:23:22.582Z"}'::jsonb),
('mcq', 5, 1, 'في خلية التحليل الكهربائي يسبب مصدر خارجي للطاقة حدوث تفاعل أكسدة واختزال غير تلقائي (الخلاصة ص 158).', '["التفاعل التلقائي يحدث في الخلية الجلفانية دون حاجة إلى مصدر خارجي.","","تفاعل التعادل لا يتضمن انتقال إلكترونات، ولا يحتاج إلى طاقة كهربائية.","الترسيب ليس ما يميز التحليل الكهربائي؛ فهو يتضمن أكسدة واختزالًا بطاقة خارجية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:23:22.582Z"}'::jsonb),
('mcq', 6, 3, 'خلية التحليل الكهربائي تحتاج إلى مصدر طاقة (جهد) خارجي يُحدث التفاعل غير التلقائي، بينما تولد الخلية الجلفانية طاقتها من تفاعلها التلقائي.', '["القنطرة الملحية مكون في الخلايا الجلفانية، وليست ما يميز خلية التحليل.","خلايا التحليل قد تستعمل قطبين من المادة نفسها، كما في الطلاء بالفضة أو تنقية النحاس.","المصباح يستهلك الطاقة في الخلية الجلفانية، ولا يلزم في خلية التحليل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:23:22.583Z"}'::jsonb),
('mcq', 7, 0, 'خلية داون (إنتاج Na وCl₂) وخلية هول–هيروليت (إنتاج Al) وخلية الطلاء بالفضة تستعمل كلها الطاقة الكهربائية لإحداث تفاعلات غير تلقائية، فهي خلايا تحليل كهربائي.', '["","خلية الوقود خلية جلفانية تنتج الكهرباء من تفاعل تلقائي.","خلية الخارصين والنحاس التي تضيء مصباحًا خلية جلفانية.","هذه كلها خلايا جلفانية تولد الكهرباء من تفاعلات تلقائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.583Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التحليل الكهربائي: استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي. خلية التحليل الكهربائي: الخلية الكهروكيميائية التي يحدث فيها تحليل كهربائي. من الأمثلة: البطارية الثانوية في أثناء إعادة شحنها، وخلية داون لتحليل مصهور NaCl (ويقبل أي مثال صحيح، ومنه: خلية التحليل الكهربائي لماء البحر، خلية هول–هيروليت، خلية تنقية النحاس، خلية الطلاء بالفضة).', '["تعريف التحليل الكهربائي","تعريف خلية التحليل الكهربائي","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التحليل الكهربائي","marks":1},{"element":"تعريف خلية التحليل الكهربائي","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريفان صحيحان ومثالان صحيحان"},{"level":"2 درجتان","description":"تعريفان صحيحان دون أمثلة أو تعريف واحد مع مثالين"},{"level":"1 درجة","description":"تعريف واحد صحيح أو أمثلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف التحليل الكهربائي بأنه إنتاج الكهرباء من تفاعل كيميائي","ذكر خلية الوقود مثالًا","ذكر البطارية في أثناء التفريغ مثالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:23:22.583Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التحليل الكهربائي هو استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي. والتفاعل الذي يحدث في خلية التحليل تفاعل أكسدة واختزال غير تلقائي، أي لا يحدث من تلقاء نفسه، وهو عكس التفاعل التلقائي الذي يحدث في الخلية الجلفانية؛ لذا تحتاج الخلية إلى مصدر طاقة خارجي يزودها بالطاقة الكهربائية اللازمة ليحدث التفاعل، فيسبب المصدر الخارجي حدوث تفاعل الأكسدة والاختزال غير التلقائي.', '["تعريف التحليل الكهربائي","تفاعل خلية التحليل غير تلقائي","المقابلة بالتفاعل التلقائي في الخلية الجلفانية","تعليل الحاجة إلى مصدر خارجي"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الربط بعدم التلقائية","marks":1},{"element":"تعليل الحاجة إلى مصدر الطاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح وربط واضح بعدم التلقائية وتعليل الحاجة إلى المصدر"},{"level":"2 درجتان","description":"تعريف صحيح مع ربط دون تعليل أو العكس"},{"level":"1 درجة","description":"تعريف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التحليل الكهربائي تفاعل تلقائي","الخلط بين التحليل الكهربائي والخلية الجلفانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:23:22.583Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تحليل كهربائي: تُستعمل الطاقة الكهربائية لاختزال Al³⁺ إلى Al، وهو تفاعل غير تلقائي. (ب) ليست تحليلًا كهربائيًا: تفاعل تلقائي ينتج الطاقة الكهربائية (خلية جلفانية). (ج) تحليل كهربائي: مصدر طاقة خارجي يؤكسد الفضة عند الأنود ويختزل Ag⁺ على الملعقة عند الكاثود. (د) ليست تحليلًا كهربائيًا: احتراق الهيدروجين في خلية الوقود تفاعل تلقائي ينتج الكهرباء.', '["(أ) تحليل كهربائي مع التعليل","(ب) ليست تحليلًا مع التعليل","(ج) تحليل كهربائي مع التعليل","(د) ليست تحليلًا مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للعمليات الأربع مع تعليل صحيح لكل منها"},{"level":"3 درجات","description":"تصنيف وتعليل صحيحان لثلاث عمليات"},{"level":"2 درجتان","description":"تصنيف صحيح للعمليات الأربع دون تعليل"},{"level":"1 درجة","description":"تصنيف صحيح لعملية أو عمليتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ خلية الوقود خلية تحليل لأنها تتعلق بالهيدروجين","التصنيف دون الاستناد إلى التعريف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:23:22.583Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
