('mcq', 4, 'التحليل الكهربائي للماء تفاعل غير تلقائي. ما الذي يجعل خلية التحليل قادرة على إنتاج الهيدروجين والأكسجين من الماء؟', null, '["تزويد الخلية بمصدر طاقة كهربائية خارجي يدفع التفاعل في الاتجاه غير التلقائي","ارتفاع درجة حرارة الماء وحدها حتى يتحلل إلى عناصره","تحول الماء إلى هيدروجين وأكسجين تلقائيًا عند تماسه بالقطبين","وجود غاز الأكسجين في الخلية الذي يعكس اتجاه التفاعل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 155 — تطبيقات التحليل الكهربائي'),
('mcq', 5, 'في خلية الوقود الهيدروجينية التي يمثل تفاعلها عكس التحليل الكهربائي للماء، أيّ المادتين تتأكسد وأيّهما تُختزل؟', null, '["يُختزل الهيدروجين ويتأكسد الأكسجين","يتأكسد الهيدروجين ويُختزل الأكسجين","يتأكسد كلٌّ من الهيدروجين والأكسجين","يُختزل كلٌّ من الهيدروجين والأكسجين"]'::jsonb, 'تطبيق', 'تحديد المؤكسد والمختزل', 'متوسط', 'الكتاب ص 155 — تطبيقات التحليل الكهربائي'),
('mcq', 6, 'في تجربة تحليل الماء كهربائيًا جُمع الغازان الناتجان عند القطبين تحت الظروف نفسها. أيّ العبارات الآتية تصف النتيجة المتوقعة؟', null, '["يتجمع H₂ عند الكاثود بحجم يساوي ضعف حجم O₂ عند الأنود","يتجمع H₂ عند الأنود بحجم يساوي ضعف حجم O₂ عند الكاثود","يتجمع O₂ عند الكاثود بحجم يساوي ضعف حجم H₂ عند الأنود","يتجمع H₂ وO₂ بحجمين متساويين عند القطبين"]'::jsonb, 'تحليل', 'تنبؤ بنتائج تجربة', 'صعب', 'الكتاب ص 155 — تطبيقات التحليل الكهربائي وتجربة «تحليل الماء كهربائيًا»'),
('mcq', 7, 'أيّ العبارات الآتية تقارن تحول الطاقة في خلية الوقود الهيدروجينية وفي التحليل الكهربائي للماء مقارنة صحيحة؟', null, '["خلية الوقود تستهلك طاقة كهربائية، والتحليل ينتجها من تفكك الماء","كلاهما ينتج طاقة كهربائية لأن موادهما واحدة","كلاهما يستهلك طاقة كهربائية لأنهما تفاعلا أكسدة واختزال","خلية الوقود تنتج طاقة كهربائية، والتحليل يستهلكها لإحداث التفاعل العكسي"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 155 — تطبيقات التحليل الكهربائي'),
('essay', 1, 'اكتب المعادلة الكلية الموزونة للتحليل الكهربائي للماء مع الحالات الفيزيائية، ثم اكتب معادلة التفاعل الكلي في خلية الوقود الهيدروجينية، وبيّن العلاقة بينهما.', null, null, 'تطبيق', 'كتابة معادلات', 'سهل', 'الكتاب ص 155 — تطبيقات التحليل الكهربائي'),
('essay', 2, 'يُنتج الهيدروجين بالتحليل الكهربائي للماء، ويُستعمل وقودًا في خلية الوقود التي تعيد تكوين الماء. فسّر لماذا لا يُعدّ ربط العمليتين معًا مصدرًا لطاقة كهربائية مجانية، مستندًا إلى اتجاه كل تفاعل وتلقائيته، ثم بيّن أهمية التحليل الكهربائي للماء.', null, null, 'تحليل', 'تفسير وربط', 'متوسط', 'الكتاب ص 155 — تطبيقات التحليل الكهربائي'),
