from (values
('mcq', 1, 1, 'يتحلل الماء بالتيار الكهربائي إلى غازي الهيدروجين والأكسجين وفق المعادلة الموزونة: 2H₂O(l) → 2H₂(g) + O₂(g).', '["المعادلة غير موزونة؛ ففي الطرف الأيمن ذرتا أكسجين مقابل ذرة واحدة في الأيسر.","","هذا تفاعل احتراق الهيدروجين في خلية الوقود، وهو عكس التحليل الكهربائي للماء.","المعادلة موزونة لكن نواتج التحليل الكهربائي للماء هي H₂ وO₂ لا فوق أكسيد الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.584Z"}'::jsonb),
('mcq', 2, 3, 'يعد التحليل الكهربائي للماء (2H₂O → 2H₂ + O₂) عكس تفاعل احتراق الهيدروجين في خلية الوقود (2H₂ + O₂ → 2H₂O).', '["تفاعل خلية الوقود 2H₂ + O₂ → 2H₂O، والتحليل الكهربائي للماء عكسه.","الأكسجين في خلية الوقود يُختزل ولا يتأكسد، والتحليل عكس التفاعل الكلي.","المواد في التفاعلين واحدة (H₂ وO₂ وH₂O)، فأحدهما عكس الآخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:23:22.584Z"}'::jsonb),
('mcq', 3, 2, 'التحليل الكهربائي للماء إحدى طرائق إنتاج الهيدروجين لاستعمالات تجارية.', '["الكلور ينتج من التحليل الكهربائي لمصهور NaCl أو لماء البحر، لا من الماء النقي.","الصوديوم ينتج في خلية داون من مصهور NaCl، لا من تحليل الماء.","","تنقية النحاس تتم في خلية تحليل محلولها كبريتات النحاس II."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:23:22.584Z"}'::jsonb),
('mcq', 4, 0, 'التفاعل غير تلقائي، فلا يحدث إلا بتزويد الخلية بطاقة كهربائية من مصدر خارجي تجبر التفاعل على السير في الاتجاه المعاكس لاتجاه تفاعل خلية الوقود التلقائي.', '["","الحرارة وحدها لا تحلل الماء في ظروف خلية التحليل؛ فالمطلوب طاقة كهربائية.","لو كان تلقائيًا لما احتاج إلى مصدر طاقة، والتفاعل هنا غير تلقائي.","الأكسجين أحد ناتجي التفاعل، وليس عاملًا يعكس اتجاهه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:23:22.584Z"}'::jsonb),
('mcq', 5, 1, 'في التفاعل 2H₂ + O₂ → 2H₂O يرتفع عدد تأكسد الهيدروجين من 0 إلى +1 فيتأكسد، وينخفض عدد تأكسد الأكسجين من 0 إلى −2 فيُختزل.', '["عدد تأكسد الهيدروجين يزداد من 0 إلى +1، فهو يتأكسد لا يُختزل.","","لا بد أن تحدث الأكسدة والاختزال معًا؛ فالأكسجين ينقص عدد تأكسده فيُختزل.","لا بد أن تحدث الأكسدة والاختزال معًا؛ فالهيدروجين يزداد عدد تأكسده فيتأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:23:22.584Z"}'::jsonb),
('mcq', 6, 0, 'من المعادلة 2H₂O → 2H₂ + O₂ تكون مولات H₂ ضعف مولات O₂، فحجمه ضعف حجم O₂ تحت الظروف نفسها. والهيدروجين ينتج بالاختزال عند الكاثود، والأكسجين بالأكسدة عند الأنود.', '["","النسبة صحيحة لكن القطبين معكوسان؛ فالهيدروجين ناتج اختزال فيتكون عند الكاثود.","عُكست النسبة والقطبان معًا؛ فمعامل H₂ ضعف معامل O₂، والأكسجين ناتج أكسدة.","معاملا الغازين في المعادلة 2 و1، فلا تتساوى الحجوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:23:22.585Z"}'::jsonb),
('mcq', 7, 3, 'في خلية الوقود يحدث تفاعل تلقائي (2H₂ + O₂ → 2H₂O) يحول الطاقة الكيميائية إلى كهربائية، أما التحليل الكهربائي للماء فيستعمل الطاقة الكهربائية لإحداث التفاعل العكسي غير التلقائي.', '["عُكس تحول الطاقة؛ فاحتراق الهيدروجين تلقائي ينتج الكهرباء، وتفكك الماء يستهلكها.","تشابه المواد لا يعني تشابه تحول الطاقة؛ فالتفاعلان متعاكسان.","تفاعل خلية الوقود تلقائي، فهو ينتج الطاقة الكهربائية ولا يستهلكها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:23:22.585Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التحليل الكهربائي للماء: 2H₂O(l) → 2H₂(g) + O₂(g). تفاعل خلية الوقود (احتراق الهيدروجين): 2H₂(g) + O₂(g) → 2H₂O(l). العلاقة: التحليل الكهربائي للماء هو عكس تفاعل احتراق الهيدروجين في خلية الوقود؛ فمتفاعلات أحدهما هي نواتج الآخر.', '["معادلة التحليل الكهربائي للماء موزونة بالحالات","معادلة خلية الوقود","العلاقة: أحدهما عكس الآخر"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة التحليل الموزونة بالحالات","marks":1},{"element":"معادلة خلية الوقود","marks":1},{"element":"بيان العلاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"معادلتان صحيحتان موزونتان مع بيان العلاقة"},{"level":"2 درجتان","description":"معادلتان صحيحتان دون بيان العلاقة أو معادلة واحدة مع العلاقة"},{"level":"1 درجة","description":"معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة H₂O → H₂ + O₂ دون موازنة","كتابة المعادلة نفسها للعمليتين","إهمال الحالات الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.585Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التحليل الكهربائي للماء 2H₂O → 2H₂ + O₂ تفاعل غير تلقائي يحتاج إلى طاقة كهربائية من مصدر خارجي، أما تفاعل خلية الوقود 2H₂ + O₂ → 2H₂O فهو عكسه وتفاعل تلقائي ينتج طاقة كهربائية. لذلك فإن الطاقة المستهلكة في التحليل لا تقل عن الطاقة الناتجة من خلية الوقود، فلا نحصل على طاقة مجانية. وأهمية التحليل الكهربائي للماء أنه إحدى طرائق إنتاج الهيدروجين الذي يُستعمل لأغراض تجارية ووقودًا.', '["التحليل غير تلقائي ويحتاج طاقة خارجية","تفاعل خلية الوقود هو العكس وتلقائي وينتج طاقة","الطاقة المستهلكة لا تقل عن الناتجة فلا طاقة مجانية","أهمية التحليل: إنتاج الهيدروجين"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه كل تفاعل وتلقائيته","marks":1.5},{"element":"تفسير عدم وجود طاقة مجانية","marks":1.5},{"element":"أهمية التحليل الكهربائي للماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يبيّن اتجاه التفاعلين وتلقائيتهما ويفسر عدم وجود طاقة مجانية ويذكر الأهمية"},{"level":"3 درجات","description":"يبيّن الاتجاه والتلقائية ويفسر دون ذكر الأهمية، أو العكس"},{"level":"2 درجتان","description":"يبيّن اتجاه التفاعلين فقط"},{"level":"1 درجة","description":"يذكر الأهمية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التفاعل التلقائي وغير التلقائي في الخليتين","الاعتقاد بأن خلية الوقود تنتج طاقة أكبر مما يستهلكه التحليل","عدّ التحليل الكهربائي للماء تفاعلًا يحدث تلقائيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:23:22.585Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المتفاعلات والنواتج: في التحليل الكهربائي يتفكك الماء إلى H₂ وO₂ (2H₂O → 2H₂ + O₂)، وفي خلية الوقود يتحد H₂ وO₂ لتكوين الماء (2H₂ + O₂ → 2H₂O)، فأحدهما عكس الآخر. التلقائية: تفاعل خلية الوقود تلقائي، وتحليل الماء غير تلقائي. تحول الطاقة: خلية الوقود تحول الطاقة الكيميائية إلى كهربائية (خلية جلفانية)، والتحليل الكهربائي يستعمل الطاقة الكهربائية لإحداث التفاعل (خلية تحليل). الأهمية: التحليل الكهربائي للماء إحدى طرائق إنتاج الهيدروجين لاستعمالات تجارية، ومنها استعماله وقودًا في خلايا الوقود.', '["المتفاعلات والنواتج متعاكسة","التلقائية: الوقود تلقائي والتحليل غير تلقائي","تحول الطاقة في كل منهما","أهمية التحليل: إنتاج الهيدروجين تجاريًا"]'::jsonb, '[]'::jsonb, '[{"element":"المتفاعلات والنواتج","marks":1},{"element":"التلقائية","marks":1},{"element":"تحول الطاقة","marks":1},{"element":"الأهمية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح صحيح في المعايير الثلاثة مع الأهمية"},{"level":"3 درجات","description":"توضيح صحيح في معيارين مع الأهمية أو الثلاثة دونها"},{"level":"2 درجتان","description":"توضيح صحيح لمعيار واحد مع الأهمية"},{"level":"1 درجة","description":"ذكر الأهمية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ تحليل الماء تلقائيًا","عكس تحول الطاقة","ذكر إنتاج الأكسجين أهميةً رئيسة بدل الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:23:22.585Z"}'::jsonb)
