('mcq', 1, 1, 'يُستعمل الكلور في جميع أنحاء العالم في تنقية المياه لأغراض الشرب والسباحة، ومركباته في المبيضات ومعالجة الورق والبلاستيك والمبيدات والأصباغ.', '["التبريد في المفاعلات النووية من استعمالات الصوديوم لا الكلور.","","مصابيح الإضاءة الخارجية الغازية تستعمل الصوديوم لا الكلور.","الوقود في خلايا الوقود هو الهيدروجين لا الكلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:23:22.586Z"}'::jsonb),
('mcq', 2, 0, 'يذكر الكتاب أن الصوديوم في حالته النقية يُستعمل مبرّدًا في المفاعلات النووية.', '["","الصوديوم ليس وقودًا نوويًا؛ فدوره في المفاعلات التبريد.","التعقيم من استعمالات الكلور ومركباته لا الصوديوم.","المبيضات المنزلية تحتوي على مركبات الكلور لا الصوديوم النقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:23:22.586Z"}'::jsonb),
('mcq', 3, 2, 'من استعمالات الصوديوم: مبرّد في المفاعلات النووية، وفي مصابيح الصوديوم الغازية المستعملة في الإضاءة الخارجية، إضافة إلى أملاحه في كثير من المنتجات.', '["تنقية مياه السباحة من استعمالات الكلور.","بوليمر كلوريد الفينيل يُصنع باستعمال الكلور.","","المبيدات تعالَج بمركبات الكلور وفق الكتاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:23:22.586Z"}'::jsonb),
('mcq', 4, 1, 'يذكر الكتاب (الشكل 4-21) أن الكلور يُستعمل في صناعة بوليمر كلوريد الفينيل الذي يُستعمل في صناعة الأنابيب.', '["الهيدروجين لا يدخل في اسم البوليمر؛ فالذي يُستعمل في صناعته هو الكلور.","","البوليمر يُصنع من الكلور، والكتاب يذكر استعماله في الأنابيب.","تبريد المفاعلات من استعمالات الصوديوم، وبوليمر كلوريد الفينيل يُستعمل في الأنابيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:23:22.586Z"}'::jsonb),
('mcq', 5, 0, 'ينتج التحليل الكهربائي لماء البحر H₂ وCl₂ وNaOH، وتكون النواتج الثلاثة جميعها مواد ذات أهمية تجارية تقوم عليها بعض الصناعات.', '["","الصوديوم والأكسجين لا ينتجان من التحليل الكهربائي لماء البحر.","هذان ناتجا خلية داون (مصهور NaCl) لا ماء البحر.","هذان ناتجا التحليل الكهربائي للماء النقي، ولا يتكون O₂ من ماء البحر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:23:22.586Z"}'::jsonb),
('mcq', 6, 2, 'المبيضات المنزلية تحتوي على مركبات الكلور، والكلور ينتج عند الأنود في خلية داون وفي خلية ماء البحر كلتيهما بتأكسد أيونات Cl⁻.', '["الكلور ينتج أيضًا عند أنود خلية ماء البحر بتأكسد Cl⁻.","الكلور ينتج أيضًا عند أنود خلية داون.","","تحليل الماء النقي ينتج H₂ وO₂ فقط، ولا يحتوي على أيونات الكلوريد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:23:22.587Z"}'::jsonb),
('mcq', 7, 3, 'الصوديوم النقي مبرّد في المفاعلات النووية (1) ويُستعمل في مصابيح الصوديوم الغازية للإضاءة الخارجية (3)، والكلور يُستعمل في صناعة بوليمر كلوريد الفينيل (2).', '["عُكس الربط كله؛ فالتبريد والإضاءة للصوديوم، وبوليمر كلوريد الفينيل للكلور.","مصابيح الإضاءة الخارجية الغازية مصابيح صوديوم لا هيدروجين.","المبرّد في المفاعلات النووية هو الصوديوم لا الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:23:22.587Z"}'::jsonb),
('essay', 1, null::int, null, null, 'استعمالات الكلور: تنقية المياه لأغراض الشرب والسباحة، وصناعة المبيضات المنزلية ومنتجات التنظيف، ومعالجة الورق والبلاستيك، وصناعة المبيدات والأصباغ والطلاء (يكفي ثلاثة). استعمالات الصوديوم: مبرّد في المفاعلات النووية، وفي مصابيح الصوديوم الغازية المستعملة في الإضاءة الخارجية.', '["ثلاثة استعمالات صحيحة للكلور","استعمالان صحيحان للصوديوم"]'::jsonb, '[]'::jsonb, '[{"element":"استعمالات الكلور (درجة لكل استعمال)","marks":3},{"element":"استعمالات الصوديوم (درجة لكل استعمال)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"ثلاثة استعمالات صحيحة للكلور واستعمالان صحيحان للصوديوم"},{"level":"3 درجات","description":"ثلاثة استعمالات صحيحة من المجموع"},{"level":"1 درجة","description":"استعمال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة تبريد المفاعلات إلى الكلور","نسبة تنقية المياه إلى الصوديوم","ذكر استعمالات الهيدروجين بدل الصوديوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:23:22.587Z"}'::jsonb),
('essay', 2, null::int, null, null, 'النواتج: غاز الهيدروجين، وغاز الكلور، ومحلول هيدروكسيد الصوديوم، وجميعها مواد ذات أهمية تجارية. يتكون الهيدروجين عند الكاثود (باختزال الماء)، ويتكون الكلور عند الأنود (بتأكسد Cl⁻). من الاستعمالات: يُستعمل الكلور في صناعة بوليمر كلوريد الفينيل الذي تُصنع منه الأنابيب (ويقبل أي استعمال صحيح، ومنه: تنقية المياه، المبيضات، إنتاج الهيدروجين لاستعمالات تجارية).', '["النواتج الثلاثة","H₂ عند الكاثود","Cl₂ عند الأنود","استعمال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"النواتج الثلاثة","marks":1},{"element":"قطب كل غاز","marks":1},{"element":"الاستعمال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"النواتج الثلاثة وقطبا الغازين واستعمال صحيح"},{"level":"2 درجتان","description":"عنصران صحيحان من الثلاثة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الصوديوم ناتجًا","عكس القطبين","ذكر الأكسجين ناتجًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:23:22.587Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تنتج خلية داون الكلور عند الأنود (2Cl⁻ → Cl₂ + 2e⁻) والصوديوم عند الكاثود (Na⁺ + e⁻ → Na). الكلور يدخل في حياة كل فرد: مياه الشرب والسباحة المعقمة به، والمبيضات المنزلية ومنتجات التنظيف التي تحتوي على مركباته، والورق والبلاستيك والمبيدات والأصباغ والطلاء التي تُعالج به. والصوديوم يُستعمل مبرّدًا في المفاعلات النووية التي تنتج الكهرباء، وفي مصابيح الصوديوم الغازية التي تضيء الشوارع، فضلًا عن أملاحه في كثير من المنتجات. لذا فإن الخلية التي تنتجهما ذات أهمية كبيرة.', '["نصف تفاعل إنتاج الكلور","نصف تفاعل إنتاج الصوديوم","مثالان على الأقل من الحياة اليومية للكلور","مثال على الأقل للصوديوم"]'::jsonb, '[]'::jsonb, '[{"element":"نصفا التفاعل","marks":2},{"element":"أمثلة الكلور","marks":1},{"element":"أمثلة الصوديوم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نصفا تفاعل صحيحان وأمثلة صحيحة للناتجين"},{"level":"3 درجات","description":"أمثلة صحيحة للناتجين مع خطأ في أحد نصفي التفاعل"},{"level":"2 درجتان","description":"أمثلة صحيحة دون معادلات"},{"level":"1 درجة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل استعمالات الناتجين","كتابة نصف تفاعل الصوديوم عند الأنود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:23:22.587Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
