from (values
('mcq', 1, 0, 'يُحصل على الألومنيوم بالتحليل الكهربائي لأكسيد الألومنيوم المستخلص من خام البوكسيت Al₂O₃·2H₂O.', '["","الكريوليت يُستعمل مصهورًا مذيبًا لأكسيد الألومنيوم، وليس الخام الذي يُستخلص منه.","الكالكوبايرايت أحد خامات النحاس لا الألومنيوم.","الملاكايت أحد خامات النحاس لا الألومنيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:23:22.588Z"}'::jsonb),
('mcq', 2, 3, 'يذوب أكسيد الألومنيوم عند 1000°C في مصهور الكريوليت الصناعي Na₃AlF₆، وهو مركب آخر للألومنيوم.', '["في المحلول المائي يُختزل الماء بدل Al³⁺، لذا تُستعمل المصاهير.","محلول كبريتات النحاس II يُستعمل في تنقية النحاس لا في إنتاج الألومنيوم.","مصهور NaCl يُستعمل في خلية داون، أما Al₂O₃ فيذاب في مصهور الكريوليت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:23:22.588Z"}'::jsonb),
('mcq', 3, 2, 'تعمل بطانة الجرافيت عمل الكاثود، وعندها تُختزل أيونات الألومنيوم: Al³⁺ + 3e⁻ → Al، فيستقر الألومنيوم المصهور في قاع الخلية.', '["هذا تأكسد أيونات الأكسيد، ويحدث عند الأنود لا الكاثود.","هذا تأكسد للألومنيوم، والمطلوب إنتاجه باختزال أيوناته عند الكاثود.","","هذا تفاعل كربون الأنود مع الأكسجين الناتج، وليس تفاعل الكاثود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:23:22.588Z"}'::jsonb),
('mcq', 4, 1, 'تُغطى الخلية من الداخل بطبقة من الجرافيت تعمل عمل الكاثود، وتُغمس أصابع أخرى من الجرافيت في المصهور لتعمل عمل الأنود.', '["أصابع الجرافيت المغموسة في المصهور تعمل عمل الأنود.","","المصهور هو الوسط الموصل (الإلكتروليت)، وليس قطبًا.","لا يُستعمل قضيب ألومنيوم قطبًا في الخلية؛ فالكاثود بطانة الجرافيت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:23:22.588Z"}'::jsonb),
('mcq', 5, 3, 'تتأكسد أيونات الأكسيد عند الأنود 2O²⁻ → O₂ + 4e⁻، ولأن درجة الحرارة عالية يتفاعل الأكسجين الناتج مع كربون الأنود C + O₂ → CO₂، فتُستهلك القضبان ويلزم استبدالها.', '["الألومنيوم يتكون عند الكاثود ويستقر في قاع الخلية، لا على الأنود.","الكتاب يعلل استهلاكها بتفاعل كربونها مع الأكسجين لا بذوبانها.","أيونات Al³⁺ تُختزل عند الكاثود ولا تتأكسد عند الأنود.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:23:22.588Z"}'::jsonb),
('mcq', 6, 1, 'بعد اختزال Al³⁺ عند الكاثود يستقر الألومنيوم المصهور في قاع الخلية، ويُسحب بصورة دورية.', '["الألومنيوم يتكون مصهورًا عند الكاثود ويستقر في القاع وفق الكتاب.","","أصابع الجرافيت أنود؛ والألومنيوم يتكون بالاختزال عند الكاثود لا عندها.","الغاز المتصاعد هو CO₂، أما الألومنيوم فيتكون فلزًا مصهورًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:23:22.589Z"}'::jsonb),
('mcq', 7, 2, 'إنتاج 4 mol Al يتطلب 4 × 3 = 12 mol e⁻ (Al³⁺ + 3e⁻ → Al)، وكل 1 mol O₂ يحرر 4 mol e⁻ (2O²⁻ → O₂ + 4e⁻)، إذن مولات O₂ = 12 ÷ 4 = 3 mol.', '["افتُرضت نسبة 1:1 بين Al وO₂ دون موازنة الإلكترونات بين نصفي التفاعل.","عُدّ كل جزيء O₂ يحتاج إلى إلكترونين فقط، والصحيح أن تكوينه يحرر 4 إلكترونات.","","هذا عدد مولات الإلكترونات المنتقلة لا مولات O₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:23:22.589Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُستعمل مادة أكسيد الألومنيوم Al₂O₃ المستخلصة من خام البوكسيت Al₂O₃·2H₂O، ويُذاب في مصهور الكريوليت الصناعي Na₃AlF₆ عند نحو 1000°C. الكاثود: بطانة من الجرافيت تغطي الخلية من الداخل، ويحدث عندها: Al³⁺ + 3e⁻ → Al، فيستقر الألومنيوم المصهور في قاع الخلية ويُسحب دوريًا. الأنود: أصابع من الجرافيت مغموسة في المصهور، ويحدث عندها تأكسد أيونات الأكسيد: 2O²⁻ → O₂ + 4e⁻، ثم يتفاعل الأكسجين مع كربون الأنود: C + O₂ → CO₂.', '["Al₂O₃ من خام البوكسيت","مصهور الكريوليت عند 1000°C","الكاثود بطانة الجرافيت وتفاعله","الأنود أصابع الجرافيت وتفاعله","تفاعل الأكسجين مع الكربون"]'::jsonb, '[]'::jsonb, '[{"element":"المادة الخام ومصدرها","marks":1},{"element":"المذيب ودرجة الحرارة","marks":1},{"element":"الكاثود ونصف تفاعله","marks":2},{"element":"الأنود ونصف تفاعله","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"وصف كامل صحيح لجميع العناصر بالمعادلات"},{"level":"4 درجات","description":"وصف صحيح للقطبين وتفاعليهما مع نقص في المواد أو الظروف"},{"level":"2 درجتان","description":"وصف صحيح للمواد والظروف دون القطبين أو أحدهما"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكريوليت خام الألومنيوم","عكس الكاثود والأنود","كتابة أكسدة Al عند الكاثود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:23:22.589Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند الأنود تتأكسد أيونات الأكسيد: 2O²⁻ → O₂ + 4e⁻. ولأن درجة الحرارة عالية (نحو 1000°C) يتفاعل الأكسجين الناتج مع كربون الأنود مكونًا ثاني أكسيد الكربون: C + O₂ → CO₂، فيُستهلك الجرافيت تدريجيًا ويجب استبدال القضبان باستمرار. أما الكاثود فيحدث عنده اختزال Al³⁺ + 3e⁻ → Al ولا يتكون عنده أكسجين، فلا يُستهلك كربونه.', '["تأكسد O²⁻ عند الأنود","تفاعل O₂ مع الكربون عند الحرارة العالية","استهلاك القضبان","عدم تكوّن الأكسجين عند الكاثود"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة تأكسد O²⁻","marks":1},{"element":"معادلة تفاعل الكربون مع الأكسجين وربطها بالحرارة","marks":2},{"element":"تفسير عدم استهلاك الكاثود","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل بالمعادلتين مع تفسير حالة الكاثود"},{"level":"3 درجات","description":"تفسير صحيح بالمعادلتين دون حالة الكاثود"},{"level":"2 درجتان","description":"تفسير لفظي صحيح دون معادلات"},{"level":"1 درجة","description":"ذكر أن القضبان تُستهلك دون سبب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الألومنيوم يتكون على الأنود","القول إن الكربون يذوب في الكريوليت","إهمال دور درجة الحرارة العالية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:23:22.589Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) n(Al) = 54.0 ÷ 26.98 = 2.00 mol. (ب) Al³⁺ + 3e⁻ → Al، إذن n(e⁻) = 3 × 2.00 = 6.00 mol. (ج) 2O²⁻ → O₂ + 4e⁻، إذن n(O₂) = 6.00 ÷ 4 = 1.50 mol. (د) C + O₂ → CO₂ بنسبة 1:1، إذن n(C) = 1.50 mol، وكتلته = 1.50 × 12.01 = 18.0 g.', '["مولات Al","مولات الإلكترونات من نصف تفاعل الكاثود","مولات O₂ من نصف تفاعل الأنود","كتلة الكربون المستهلكة"]'::jsonb, '["n(Al) = 54.0 g ÷ 26.98 g/mol = 2.00 mol","n(e⁻) = 3 × n(Al) = 6.00 mol","n(O₂) = n(e⁻) ÷ 4 = 1.50 mol","n(C) = n(O₂) = 1.50 mol ← m(C) = 1.50 × 12.01 = 18.0 g"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة للأجزاء الأربعة بالوحدات والأرقام المعنوية"},{"level":"3 درجات","description":"ثلاثة أجزاء صحيحة"},{"level":"2 درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان ضرب مولات Al في 3","قسمة مولات الإلكترونات على 2 بدل 4","استعمال الكتلة المولية لـ CO₂ بدل C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:23:22.589Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C4-L3-O09') and x.type = v.type and x.number = v.number
