select (select id from public.objectives where code = 'K3-C4-L3-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما السبب الأوّلي لإعادة تدوير الألومنيوم؟', null, '["ندرة خام البوكسيت في القشرة الأرضية","ارتفاع سعر الكريوليت المستعمل مذيبًا","صعوبة صهر الألومنيوم في الأفران","الكمية الهائلة من الكهرباء اللازمة لإنتاجه من خامه"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 157 — إنتاج الألومنيوم وإعادة تدويره'),
('mcq', 2, 'ما الطاقة الوحيدة اللازمة لجعل الألومنيوم المعاد تدويره قابلًا للاستعمال؟', null, '["الكهرباء اللازمة لاختزال أيوناته مرة أخرى","الحرارة اللازمة لإذابة البوكسيت في الكريوليت","الحرارة التي يتطلبها صهره في الفرن","الكهرباء اللازمة لأكسدة أيونات الأكسيد"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 157 — إنتاج الألومنيوم وإعادة تدويره'),
('mcq', 3, 'لماذا تُقام مصانع إنتاج الألومنيوم بطريقة هول–هيروليت قريبًا من محطات الطاقة الكهربائية؟', null, '["لأن محطات الطاقة تنتج الكريوليت اللازم للعملية","لأن العملية تستهلك كميات ضخمة من الطاقة الكهربائية فتقل تكلفتها","لأن الألومنيوم يُستعمل وقودًا في محطات الطاقة","لأن غاز CO₂ الناتج يُستعمل في تبريد محطات الطاقة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 157 — إنتاج الألومنيوم وإعادة تدويره'),
('mcq', 4, 'لماذا لا يحتاج الألومنيوم المعاد تدويره إلى التحليل الكهربائي مرة أخرى؟', null, '["لأنه فلز سبق اختزال أيوناته، فيكفي صهره وإعادة تشكيله","لأنه يتحول عند صهره إلى أكسيد الألومنيوم تلقائيًا","لأن أيوناته تُختزل تلقائيًا عند تسخينها في الفرن","لأن العلب المستعملة تحتوي على الكريوليت مسبقًا"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 157 — إنتاج الألومنيوم وإعادة تدويره'),
('mcq', 5, 'كم مولًا من الإلكترونات يلزم لإنتاج 1.00 kg من الألومنيوم بطريقة هول–هيروليت؟ (Al = 26.98 g/mol)', null, '["37.1 mol","0.111 mol","333 mol","111 mol"]'::jsonb, 'تطبيق', 'حساب مولات', 'متوسط', 'الكتاب ص 157 — إنتاج الألومنيوم وإعادة تدويره'),
('mcq', 6, 'لماذا يحتاج إنتاج 1 kg من الفضة من أيوناتها بالتحليل الكهربائي إلى طاقة كهربائية أقل من إنتاج 1 kg من الألومنيوم من أيوناته؟ (Ag = 107.87 ، Al = 26.98 g/mol)', null, '["لأن 1 kg من Al يحتاج إلى نحو 111 mol e⁻ مقابل نحو 9.27 mol e⁻ للفضة","لأن 1 kg من Ag يحتاج إلى نحو 111 mol e⁻ مقابل نحو 9.27 mol e⁻ للألومنيوم","لأن عدد الإلكترونات اللازم للكيلوجرام متساوٍ لكن الفضة أسهل انصهارًا","لأن 1 kg من Al يحتاج إلى نحو 37.1 mol e⁻ مقابل نحو 9.27 mol e⁻ للفضة"]'::jsonb, 'تحليل', 'مقارنة كمية', 'صعب', 'الكتاب ص 158 — التقويم 4-3 (السؤال 27)'),
('mcq', 7, 'في نقاش حول تشجيع جمع علب الألومنيوم الفارغة، أيّ الحجج الآتية هي الأقوى علميًا؟', null, '["الألومنيوم المعاد تدويره أنقى دائمًا من المنتج من الخام","إعادة التدوير توفر الكريوليت لأنه المستهلك الرئيس للطاقة","إعادة التدوير تحتاج إلى حرارة الصهر فقط بدل الكهرباء الهائلة للتحليل","الألومنيوم المعاد تدويره لا يحتاج إلى أي طاقة لإعادة تشكيله"]'::jsonb, 'تقويم', 'تقويم حجج', 'صعب', 'الكتاب ص 157 — إنتاج الألومنيوم وإعادة تدويره'),
('essay', 1, 'علّل أهمية إعادة تدوير الألومنيوم، بالرجوع إلى عملية هول–هيروليت.', null, null, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 157–158 — إعادة تدوير الألومنيوم والتقويم 4-3 (السؤال 25)'),
('essay', 2, 'احسب عدد مولات الإلكترونات اللازمة لإنتاج 1.00 kg من كل من الألومنيوم (من Al³⁺) والفضة (من Ag⁺) بالتحليل الكهربائي، ثم استعمل النتيجة لتفسير لماذا يُعد إنتاج الألومنيوم من خامه مستهلكًا كبيرًا للكهرباء، وما علاقة ذلك بأهمية إعادة تدويره. (Al = 26.98 ، Ag = 107.87 g/mol)', null, null, 'تحليل', 'حساب وتفسير', 'صعب', 'الكتاب ص 157–158 — إنتاج الألومنيوم والتقويم 4-3 (السؤال 27)'),
('essay', 3, 'قارن بين صنع علبة ألومنيوم من خام البوكسيت وصنعها من علبة معاد تدويرها من حيث: الخطوات الأساسية، ونوع الطاقة المستهلكة، ثم فسّر لماذا تُقام مصانع الإنتاج من الخام قرب محطات الطاقة بينما لا يلزم ذلك لمصانع إعادة التدوير.', null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 157 — إنتاج الألومنيوم وإعادة تدويره')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
