select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الكمية الهائلة من الكهرباء التي يتطلبها إنتاج الألومنيوم من الخام بطريقة هول–هيروليت هي السبب الأوّلي لإعادة تدويره.', '["الكتاب يربط إعادة التدوير بكمية الكهرباء الهائلة لا بندرة الخام.","الكريوليت ليس المستهلك الرئيس للتكلفة؛ فالعامل الحاسم استهلاك الكهرباء.","صهر الألومنيوم المعاد تدويره هو الطاقة الوحيدة التي يحتاج إليها، وهي أقل بكثير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:23:22.590Z"}'::jsonb),
('mcq', 2, 2, 'الألومنيوم المعاد تدويره قد حُلّل كهربائيًا من قبل، لذا فالطاقة الوحيدة اللازمة لجعله قابلًا للاستعمال هي الحرارة التي يتطلبها صهره في الفرن.', '["الألومنيوم المعاد تدويره فلز سبق اختزاله، فلا يحتاج إلى تحليل كهربائي ثانية.","إذابة Al₂O₃ في الكريوليت خطوة في الإنتاج من الخام لا في إعادة التدوير.","","أكسدة O²⁻ تفاعل أنود في خلية هول–هيروليت، ولا تحدث في إعادة التدوير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:23:22.590Z"}'::jsonb),
('mcq', 3, 1, 'تستخدم عملية هول–هيروليت كميات ضخمة من الطاقة الكهربائية، لذا يتم إنتاج الألومنيوم في مصانع قريبة من محطات الطاقة؛ حيث تقل تكلفة الطاقة الكهربائية.', '["محطات الطاقة لا تنتج الكريوليت؛ فهو مركب صناعي يُحضَّر مستقلًا.","","الألومنيوم ليس وقودًا لمحطات الطاقة؛ والسبب حاجة المصنع إلى الكهرباء.","لا يُستعمل CO₂ الناتج في تبريد المحطات؛ والسبب تكلفة الكهرباء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:23:22.590Z"}'::jsonb),
('mcq', 4, 0, 'الألومنيوم المعاد تدويره قد حُلّل كهربائيًا من قبل، أي إنه فلز (Al) لا أيونات (Al³⁺)، فلا يلزم اختزاله ثانية، وتكفي حرارة صهره.', '["","الصهر لا يحول الفلز إلى أكسيد؛ والفلز المصهور يُعاد تشكيله مباشرة.","اختزال Al³⁺ غير تلقائي؛ وإعادة التدوير لا تتضمن اختزالًا أصلًا.","العلب المستعملة لا تحتوي على الكريوليت، ولا علاقة لذلك بإعادة التدوير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:23:22.590Z"}'::jsonb),
('mcq', 5, 3, 'n(Al) = 1000 g ÷ 26.98 g/mol = 37.1 mol، ومن Al³⁺ + 3e⁻ → Al تكون n(e⁻) = 3 × 37.1 = 111 mol، وهي كمية كبيرة تفسر الاستهلاك الضخم للكهرباء.', '["هذا عدد مولات Al؛ نُسي ضربه في 3 إلكترونات لكل أيون Al³⁺.","لم تُحوَّل الكتلة من kg إلى g قبل القسمة على الكتلة المولية.","ضُرب في 3 مرتين، أو استُعمل 9 إلكترونات لكل ذرة بدل 3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:23:22.590Z"}'::jsonb),
('mcq', 6, 0, 'للألومنيوم: (1000 ÷ 26.98) × 3 = 111 mol e⁻، وللفضة: (1000 ÷ 107.87) × 1 = 9.27 mol e⁻؛ فالألومنيوم يحتاج إلى نحو 12 ضعفًا من الإلكترونات (الكهرباء)، لصغر كتلته المولية وشحنة أيونه +3.', '["","عُكست القيمتان؛ فالفضة أكبر كتلة مولية وتحتاج إلى إلكترون واحد لكل أيون.","عدد الإلكترونات غير متساوٍ: نحو 111 mol للألومنيوم مقابل 9.27 mol للفضة.","37.1 mol هي مولات Al لا الإلكترونات؛ فكل أيون Al³⁺ يحتاج إلى 3 إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:23:22.591Z"}'::jsonb),
('mcq', 7, 2, 'إنتاج الألومنيوم من خامه يتطلب كمية هائلة من الكهرباء، أما المعاد تدويره فلا يحتاج إلا إلى حرارة صهره؛ لذا يوفر كل طن معاد تدويره كمية كبيرة من الطاقة الكهربائية (الشكل 4-22).', '["الكتاب لا يربط إعادة التدوير بالنقاوة؛ فالحجة العلمية هي توفير الطاقة.","الكريوليت مذيب في الخلية، والمستهلك الرئيس للطاقة هو التحليل الكهربائي.","","يحتاج إلى حرارة الصهر في الفرن، فالقول إنه لا يحتاج إلى أي طاقة خطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:23:22.591Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تستخدم عملية هول–هيروليت كميات ضخمة من الطاقة الكهربائية لاختزال أيونات Al³⁺ إلى فلز الألومنيوم (Al³⁺ + 3e⁻ → Al)، حتى إن المصانع تُقام قرب محطات الطاقة لتقليل تكلفة الكهرباء. أما الألومنيوم المعاد تدويره فقد حُلّل كهربائيًا من قبل، فالطاقة الوحيدة اللازمة لجعله قابلًا للاستعمال هي الحرارة التي يتطلبها صهره في الفرن. لذا فإعادة التدوير توفر كميات كبيرة من الطاقة الكهربائية، وهذه الكمية الهائلة من الكهرباء هي السبب الأوّلي لإعادة تدويره.', '["عملية هول–هيروليت تستهلك كميات ضخمة من الكهرباء","المعاد تدويره سبق اختزاله","إعادة التدوير تحتاج إلى حرارة الصهر فقط","النتيجة: توفير كبير في الطاقة الكهربائية"]'::jsonb, '[]'::jsonb, '[{"element":"استهلاك هول–هيروليت للكهرباء","marks":1},{"element":"المعاد تدويره لا يحتاج إلى تحليل كهربائي","marks":1},{"element":"الطاقة اللازمة لإعادة التدوير: الصهر فقط","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل يربط استهلاك الكهرباء بالعملية وحاجة المعاد تدويره إلى الصهر فقط"},{"level":"2 درجتان","description":"ذكر استهلاك الكهرباء مع نقص في تفسير حالة المعاد تدويره"},{"level":"1 درجة","description":"ذكر توفير الطاقة دون ربط بالعملية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل الأهمية بأسباب بيئية فقط دون ذكر الطاقة الكهربائية","القول إن المعاد تدويره لا يحتاج إلى أي طاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:23:22.591Z"}'::jsonb),
('essay', 2, null::int, null, null, 'للألومنيوم: n(Al) = 1000 ÷ 26.98 = 37.1 mol، ومن Al³⁺ + 3e⁻ → Al: n(e⁻) = 3 × 37.1 = 111 mol. للفضة: n(Ag) = 1000 ÷ 107.87 = 9.27 mol، ومن Ag⁺ + e⁻ → Ag: n(e⁻) = 9.27 mol. إذن يحتاج الكيلوجرام من الألومنيوم إلى نحو 12 ضعف الإلكترونات (الكهرباء) التي يحتاج إليها الكيلوجرام من الفضة؛ بسبب صغر الكتلة المولية للألومنيوم (ذرات أكثر في الكيلوجرام) وشحنة أيونه +3. ولأن إنتاج الألومنيوم من خامه يستهلك هذه الكمية الهائلة من الكهرباء، فإعادة تدويره (التي تحتاج إلى حرارة الصهر فقط) توفر طاقة كبيرة.', '["مولات Al ومولات الإلكترونات له","مولات Ag ومولات الإلكترونات لها","النسبة نحو 12 وسببها","الربط بأهمية إعادة التدوير"]'::jsonb, '["n(Al) = 1000 ÷ 26.98 = 37.1 mol ← n(e⁻) = 3 × 37.1 = 111 mol","n(Ag) = 1000 ÷ 107.87 = 9.27 mol ← n(e⁻) = 9.27 mol","111 ÷ 9.27 ≈ 12","التفسير: كتلة مولية أصغر وشحنة +3 ← كهرباء أكثر ← أهمية إعادة التدوير"]'::jsonb, '[{"element":"حساب الألومنيوم","marks":2},{"element":"حساب الفضة","marks":1},{"element":"التفسير","marks":1},{"element":"الربط بإعادة التدوير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان مع تفسير وربط صحيحين"},{"level":"3 درجات","description":"حسابان صحيحان دون تفسير أو ربط كافيين"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان ضرب مولات Al في 3","عدم تحويل kg إلى g","تفسير الفرق بدرجة الانصهار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:23:22.591Z"}'::jsonb),
('essay', 3, null::int, null, null, 'من الخام: يُستخلص Al₂O₃ من البوكسيت ويُذاب في مصهور الكريوليت عند نحو 1000°C، ثم يُحلل كهربائيًا فتُختزل أيونات Al³⁺ عند الكاثود (Al³⁺ + 3e⁻ → Al)، والطاقة المستهلكة أساسًا كهربائية بكميات ضخمة إضافة إلى الحرارة. من المعاد تدويره: يُصهر الألومنيوم في الفرن ويُعاد تشكيله، والطاقة المستهلكة حرارة الصهر فقط؛ لأن الفلز سبق اختزاله. لذا تُقام مصانع الإنتاج من الخام قرب محطات الطاقة لتقل تكلفة الطاقة الكهربائية الضخمة التي تحتاج إليها، أما إعادة التدوير فلا تحتاج إلى التحليل الكهربائي فلا يلزمها ذلك.', '["خطوات الإنتاج من الخام","خطوات إعادة التدوير","نوع الطاقة في كل منهما","تفسير موقع المصانع"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات الإنتاج من الخام","marks":1},{"element":"خطوات إعادة التدوير","marks":1},{"element":"نوع الطاقة في كل منهما","marks":1},{"element":"تفسير موقع المصانع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة كاملة مع تفسير موقع المصانع"},{"level":"3 درجات","description":"مقارنة صحيحة دون تفسير موقع المصانع"},{"level":"2 درجتان","description":"مقارنة صحيحة لنوع الطاقة فقط مع تفسير"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن إعادة التدوير تحتاج إلى تحليل كهربائي أيضًا","إغفال الكهرباء في الإنتاج من الخام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:23:22.591Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
