('mcq', 2, 'ما الذي يعمل أنودًا في خلية تنقية النحاس؟', null, '["قوالب كبيرة وسميكة من النحاس غير النقي","شريحة رقيقة من النحاس النقي","قضبان من الجرافيت المغموسة في المحلول","قطعة من الفضة النقية"]'::jsonb, 'فهم', 'تحديد مكونات', 'سهل', 'الكتاب ص 157–158 — تنقية الخامات (تنقية النحاس)'),
