('mcq', 3, 3, 'كاثود الخلية شريحة رقيقة من النحاس النقي، تنتقل إليها أيونات النحاس II خلال المحلول فتُختزل إلى ذرات نحاس (Cu²⁺ + 2e⁻ → Cu) تصبح جزءًا من الكاثود.', '["هذا وصف الأنود؛ فالنحاس غير النقي يتأكسد ويذوب في المحلول.","القطب صحيح لكن التفاعل خطأ؛ فعند الكاثود يحدث اختزال لا أكسدة.","النحاس غير النقي هو الأنود، ولا يحدث عنده اختزال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:23:22.592Z"}'::jsonb),
('mcq', 4, 2, 'خلال مرور التيار تتأكسد ذرات النحاس غير النقي عند الأنود إلى أيونات النحاس II: Cu → Cu²⁺ + 2e⁻.', '["هذا اختزال يحدث عند الكاثود لا الأنود.","الكتاب يذكر أن النحاس يتأكسد إلى أيونات النحاس II (Cu²⁺) لا Cu⁺.","","هذا تفاعل استخلاص النحاس من خامه بالتسخين، وليس تفاعل الأنود في التنقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:23:22.592Z"}'::jsonb),
('mcq', 5, 1, 'تتأكسد ذرات النحاس عند الأنود وتنتقل أيوناتها إلى الكاثود، في حين تترسب الشوائب في قاع الخلية، فيتجمع النحاس النقي على الكاثود.', '["لو ترسبت على الكاثود لما كان النحاس الناتج نقيًا.","","الكتاب يذكر أن الشوائب تترسب في قاع الخلية لا أنها تتصاعد.","الشوائب مواد غير النحاس فلا تتحول إليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:23:22.593Z"}'::jsonb),
('mcq', 6, 3, 'يتأكسد النحاس غير النقي عند الأنود ويذوب (Cu → Cu²⁺ + 2e⁻) فتقل كتلته، وتُختزل الأيونات عند الكاثود وتصبح ذراتها جزءًا منه فتزداد كتلته.', '["عُكس التغير؛ فالأنود يتأكسد ويذوب، والكاثود يترسب عليه النحاس.","الكاثود يكتسب ذرات نحاس فتزداد كتلته.","النحاس ينتقل من الأنود إلى الكاثود، فتتغير الكتلتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:23:22.593Z"}'::jsonb),
('mcq', 7, 0, 'من Cu²⁺ + 2e⁻ → Cu: n(Cu) = 0.500 ÷ 2 = 0.250 mol، والكتلة = 0.250 × 63.55 = 15.9 g.', '["","عُدّ كل إلكترون يرسّب ذرة نحاس، والصحيح أن Cu²⁺ يحتاج إلى إلكترونين.","قُسمت مولات الإلكترونات على 4 بدل 2.","استُعملت الكتلة المولية كاملة كأن 1 mol من النحاس قد ترسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:23:22.593Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُصب النحاس غير النقي في قوالب كبيرة وسميكة تُستعمل أنودًا في خلية تحليل كهربائي تحتوي على محلول كبريتات النحاس II، والكاثود شريحة رقيقة من النحاس النقي. عند مرور التيار تتأكسد ذرات النحاس غير النقي عند الأنود: Cu → Cu²⁺ + 2e⁻، وتنتقل أيونات النحاس II خلال المحلول إلى الكاثود فتُختزل: Cu²⁺ + 2e⁻ → Cu، وتصبح الذرات جزءًا من الكاثود، في حين تترسب الشوائب في قاع الخلية.', '["الأنود: نحاس غير نقي","الكاثود: شريحة نحاس نقي","المحلول: كبريتات النحاس II","تفاعل الأنود","تفاعل الكاثود","الشوائب تترسب في القاع"]'::jsonb, '[]'::jsonb, '[{"element":"الأنود والكاثود","marks":2},{"element":"المحلول","marks":1},{"element":"نصفا التفاعل","marks":2},{"element":"مصير الشوائب","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"وصف كامل صحيح لجميع العناصر"},{"level":"4 درجات","description":"وصف صحيح للأقطاب والمحلول مع خطأ في نصف تفاعل أو إغفال الشوائب"},{"level":"2 درجتان","description":"تحديد الأقطاب فقط صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الأنود والكاثود","القول إن الشوائب تترسب على الكاثود","كتابة اختزال عند الأنود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:23:22.593Z"}'::jsonb),
('essay', 2, null::int, null, null, 'معادلة الاستخلاص: Cu₂S(s) + O₂(g) → 2Cu(s) + SO₂(g). النحاس المستخلص بهذه العملية يحتوي على الكثير من الشوائب، لذا يلزم تنقيته بالتحليل الكهربائي. في خلية التنقية يتأكسد النحاس غير النقي عند الأنود إلى Cu²⁺، وتنتقل الأيونات إلى الكاثود (شريحة النحاس النقي) فتُختزل وتصبح ذراتها جزءًا منه؛ فينتهي النحاس النقي على الكاثود، وتبقى الشوائب في قاع الخلية.', '["معادلة الاستخلاص الموزونة","النحاس المستخلص يحتوي على شوائب كثيرة","النحاس النقي يتجمع على الكاثود"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة الموزونة","marks":1},{"element":"تفسير الحاجة إلى التنقية","marks":1},{"element":"مكان النحاس النقي مع التوضيح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"معادلة صحيحة وتفسير صحيح وتحديد صحيح لمكان النحاس النقي"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الناتج Cu بدل 2Cu","القول إن النحاس النقي يبقى عند الأنود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:23:22.593Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) Cu → Cu²⁺ + 2e⁻، إذن n(e⁻) = 2 × 0.300 = 0.600 mol. (ب) Cu²⁺ + 2e⁻ → Cu، إذن n(Cu) = 0.600 ÷ 2 = 0.300 mol، والكتلة = 0.300 × 63.55 = 19.1 g. التحليل: الأنود نحاس غير نقي، فإلى جانب النحاس الذي يتأكسد تنفصل منه الشوائب وتترسب في قاع الخلية؛ فيفقد الأنود كتلة النحاس والشوائب معًا، بينما يكتسب الكاثود النحاس النقي فقط.', '["مولات الإلكترونات","كتلة النحاس المترسب","تفسير فرق الكتلتين بالشوائب"]'::jsonb, '["n(e⁻) = 2 × n(Cu) = 2 × 0.300 = 0.600 mol","n(Cu المترسب) = 0.600 ÷ 2 = 0.300 mol","m = 0.300 × 63.55 = 19.1 g"]'::jsonb, '[{"element":"(أ) مولات الإلكترونات","marks":1},{"element":"(ب) كتلة النحاس","marks":2},{"element":"التحليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان بالوحدات وتحليل صحيح"},{"level":"3 درجات","description":"حسابان صحيحان دون تحليل صحيح"},{"level":"2 درجتان","description":"حساب واحد صحيح مع تحليل صحيح"},{"level":"1 درجة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال إلكترون واحد لكل ذرة نحاس","القول إن الكتلتين متساويتان دائمًا","نسيان الشوائب في التحليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:23:22.593Z"}'::jsonb)
