('mcq', 3, 'ما نصف التفاعل الذي يحدث عند الكاثود في خلية الطلاء بالفضة؟', null, '["Ag → Ag⁺ + e⁻","Ag²⁺ + 2e⁻ → Ag","Ag⁺ + e⁻ → Ag","2H₂O + 2e⁻ → H₂ + 2OH⁻"]'::jsonb, 'فهم', 'تحديد نصف تفاعل', 'متوسط', 'الكتاب ص 158 — الطلاء بالكهرباء'),
('mcq', 4, 'ماذا يحدث لقطعة الفضة النقية (الأنود) في أثناء الطلاء الكهربائي بالفضة؟', null, '["تُختزل عليها أيونات Ag⁺ فتزداد كتلتها","تتأكسد ذراتها إلى أيونات Ag⁺ فتقل كتلتها","تبقى دون تغير لأنها نقية","تتأكسد ذراتها إلى أيونات Ag⁺ فتزداد كتلتها"]'::jsonb, 'فهم', 'وصف', 'متوسط', 'الكتاب ص 158 — الطلاء بالكهرباء'),
('mcq', 5, 'لماذا يجب مراقبة شدة التيار المار في خلية الطلاء الكهربائي والتحكم فيها؟', null, '["لمنع تأكسد الفضة عند الأنود","لجعل التفاعل في الخلية تلقائيًا","للحصول على طبقة تغليف فلزية ناعمة ومتساوية","لتحويل أيونات Ag⁺ إلى Ag²⁺"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 158 — الطلاء بالكهرباء'),
('mcq', 6, 'يراد طلاء خاتم بالذهب في خلية تحليل كهربائي. ما الأنود والكاثود في هذه الخلية؟', null, '["الأنود الخاتم، والكاثود قطعة ذهب نقي","الأنود والكاثود قطعتان من الذهب النقي","الأنود قطعة فضة نقية، والكاثود الخاتم","الأنود قطعة ذهب نقي، والكاثود الخاتم"]'::jsonb, 'تطبيق', 'تطبيق على حالة جديدة', 'صعب', 'الكتاب ص 158 — الطلاء بالكهرباء والتقويم 4-3 (السؤال 26)'),
('mcq', 7, 'في خلية لطلاء جسم بالفضة مرّ 0.0200 mol من الإلكترونات. ما كتلة الفضة المترسبة على الجسم؟ (Ag = 107.87 g/mol)', null, '["2.16 g","1.08 g","4.31 g","0.000185 g"]'::jsonb, 'تطبيق', 'حساب كتلة', 'صعب', 'الكتاب ص 158 — الطلاء بالكهرباء'),
('essay', 1, 'صِف طلاء ملعقة بطبقة من الفضة كهربائيًا، محددًا: القطب الذي توصل به الملعقة، والأنود، ونصف التفاعل عند كل قطب، ودور مصدر الطاقة.', null, null, 'فهم', 'وصف عملية', 'متوسط', 'الكتاب ص 158 — الطلاء بالكهرباء'),
('essay', 2, 'حدد الأنود والكاثود في خلية تحليل كهربائي يُستعمل فيها الذهب لطلاء المجوهرات، مع التعليل، ثم اذكر سببًا يدعو إلى التحكم في شدة التيار، ومثالًا آخر على الطلاء الكهربائي.', null, null, 'تطبيق', 'تطبيق وتعليل', 'متوسط', 'الكتاب ص 158 — الطلاء بالكهرباء والتقويم 4-3 (السؤال 26)'),
('essay', 3, 'يتم طلاء الأشياء كهربائيًا بالفضة بطريقة تشبه طريقة تنقية النحاس. حلّل أوجه الشبه والاختلاف بين العمليتين من حيث: مادة الأنود، ومادة الكاثود، والتفاعل عند كل قطب، والهدف من العملية.', null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 158 — تنقية النحاس والطلاء بالكهرباء')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
