insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يوصل الجسم المراد طلاؤه بكاثود خلية التحليل الكهربائي؛ حيث تُختزل أيونات الفضة إلى ذرات فضة تترسب على الجسم.', '["الأنود قطعة الفضة النقية التي تتأكسد؛ ولو وُصلت به الملعقة لتآكلت بدل أن تُطلى.","","خلية الطلاء لا تحتوي على قنطرة ملحية، والقنطرة ليست قطبًا.","لا يمكن وصل الجسم بالقطبين معًا؛ فهو يوصل بالكاثود فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.595Z"}'::jsonb),
('mcq', 2, 0, 'يكون الأنود في خلية الطلاء بالفضة قطعة فضة نقية تتأكسد إلى أيونات الفضة.', '["","الجسم المراد طلاؤه يوصل بالكاثود لا الأنود.","قضبان الجرافيت أنود في خلية هول–هيروليت لا في الطلاء بالفضة.","شريحة النحاس النقي كاثود في خلية تنقية النحاس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.595Z"}'::jsonb),
('mcq', 3, 2, 'عند الكاثود تُختزل أيونات الفضة بإلكترونات من مصدر الطاقة الخارجي: Ag⁺ + e⁻ → Ag، فتكوّن الفضة طبقة رقيقة تغلف الجسم.', '["هذا تأكسد الفضة، ويحدث عند الأنود لا الكاثود.","أيون الفضة في هذه الخلية أحادي الشحنة Ag⁺ وفق الكتاب.","","هذا اختزال الماء، أما في الطلاء فتُختزل أيونات الفضة وتترسب على الجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.595Z"}'::jsonb),
('mcq', 4, 1, 'عند الأنود تتأكسد الفضة إلى أيونات Ag⁺ (Ag → Ag⁺ + e⁻) عند انتزاع الإلكترونات منها بواسطة مصدر الطاقة، فتنتقل الأيونات إلى المحلول وتقل كتلة القطعة.', '["الاختزال وزيادة الكتلة يحدثان عند الكاثود (الجسم المطلي).","","قطعة الفضة تتأكسد فعلًا عند انتزاع الإلكترونات منها بواسطة مصدر الطاقة.","التأكسد يحول الذرات إلى أيونات تنتقل إلى المحلول، فتقل الكتلة ولا تزداد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:23:22.595Z"}'::jsonb),
('mcq', 5, 2, 'ينص الكتاب على أنه يجب مراقبة شدة التيار المار في الخلية والتحكم فيها للحصول على طبقة تغليف فلزية ناعمة ومتساوية.', '["تأكسد الفضة عند الأنود مطلوب ليمد المحلول بأيونات Ag⁺.","التحكم في التيار لا يجعل التفاعل تلقائيًا؛ فهو يظل غير تلقائي.","","لا يهدف الطلاء إلى تغيير شحنة أيونات الفضة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:23:22.595Z"}'::jsonb),
('mcq', 6, 3, 'بالقياس على الطلاء بالفضة: الأنود قطعة من الفلز المطلي به (الذهب النقي) تتأكسد وتمد المحلول بأيوناته، والكاثود الجسم المراد طلاؤه (الخاتم) تُختزل عليه أيونات الذهب.', '["عُكس القطبان؛ فلو كان الخاتم أنودًا لتأكسد وتآكل بدل أن يُطلى.","الجسم المراد طلاؤه يجب أن يكون أحد القطبين (الكاثود).","قطعة الفضة تمد المحلول بأيونات الفضة فيُطلى الخاتم بالفضة لا بالذهب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:23:22.596Z"}'::jsonb),
('mcq', 7, 0, 'من Ag⁺ + e⁻ → Ag: n(Ag) = n(e⁻) = 0.0200 mol، والكتلة = 0.0200 × 107.87 = 2.16 g.', '["","افتُرض أن كل ذرة فضة تحتاج إلى إلكترونين، والصحيح Ag⁺ + e⁻ → Ag.","ضُربت مولات الإلكترونات في 2 دون مبرر، فأعطى ضعف الكتلة.","قُسمت المولات على الكتلة المولية بدل ضربها فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:23:22.596Z"}'::jsonb),
('essay', 1, null::int, null, null, 'توصل الملعقة (الجسم المراد طلاؤه) بكاثود خلية التحليل الكهربائي، ويكون الأنود قطعة فضة نقية، والمحلول يحتوي على أيونات الفضة. عند الأنود تتأكسد الفضة إلى أيونات الفضة عند انتزاع الإلكترونات منها بواسطة مصدر الطاقة: Ag → Ag⁺ + e⁻. وعند الكاثود تُختزل أيونات الفضة بإلكترونات من مصدر الطاقة الخارجي: Ag⁺ + e⁻ → Ag، فتترسب الفضة طبقة رقيقة تغلف الملعقة. ودور مصدر الطاقة انتزاع الإلكترونات من الأنود وتزويد الكاثود بها لإحداث التفاعل غير التلقائي.', '["الملعقة توصل بالكاثود","الأنود قطعة فضة نقية","نصف تفاعل الأنود","نصف تفاعل الكاثود","دور مصدر الطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"الملعقة بالكاثود","marks":1},{"element":"الأنود فضة نقية","marks":1},{"element":"نصفا التفاعل","marks":2},{"element":"دور مصدر الطاقة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل صحيح لجميع العناصر"},{"level":"3 درجات","description":"تحديد صحيح للقطبين ونصفي التفاعل دون دور المصدر، أو مع خطأ في نصف تفاعل"},{"level":"1 درجة","description":"تحديد صحيح لقطب واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصل الملعقة بالأنود","كتابة Ag⁺ + e⁻ → Ag عند الأنود","إغفال حاجة الخلية إلى مصدر طاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:23:22.596Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأنود: قطعة من الذهب النقي؛ لأنها تتأكسد فتمد المحلول بأيونات الذهب. الكاثود: قطعة المجوهرات المراد طلاؤها؛ لأن أيونات الذهب تُختزل عندها إلى ذرات ذهب تترسب عليها مكونة طبقة رقيقة. يجب التحكم في شدة التيار للحصول على طبقة تغليف فلزية ناعمة ومتساوية. ومن الأمثلة الأخرى: طلاء الأجزاء الفولاذية في السيارات مثل ماصات الصدمات بالنيكل أولًا ثم بالكروم لتكون مقاومة للتآكل (ويقبل: الطلاء بالفضة).', '["الأنود ذهب نقي مع التعليل","الكاثود المجوهرات مع التعليل","سبب التحكم في التيار","مثال آخر صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"الأنود مع التعليل","marks":1},{"element":"الكاثود مع التعليل","marks":1},{"element":"سبب التحكم في التيار","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح للقطبين بتعليل مع السبب والمثال"},{"level":"3 درجات","description":"تحديد صحيح للقطبين بتعليل مع السبب أو المثال"},{"level":"2 درجتان","description":"تحديد صحيح للقطبين فقط"},{"level":"1 درجة","description":"تحديد صحيح لقطب واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس القطبين","القول إن التحكم في التيار يجعل التفاعل تلقائيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:23:22.596Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أوجه الشبه: في العمليتين يتأكسد فلز الأنود إلى أيوناته (Cu → Cu²⁺ + 2e⁻ ، Ag → Ag⁺ + e⁻)، وتنتقل الأيونات خلال المحلول إلى الكاثود فتُختزل إلى ذرات الفلز التي تترسب عليه (Cu²⁺ + 2e⁻ → Cu ، Ag⁺ + e⁻ → Ag)، وكلتاهما تحتاج إلى مصدر طاقة خارجي. أوجه الاختلاف: الأنود في التنقية نحاس غير نقي، وفي الطلاء فضة نقية؛ والكاثود في التنقية شريحة نحاس نقي، وفي الطلاء الجسم المراد طلاؤه (قد يكون من فلز آخر)؛ والهدف في التنقية فصل النحاس عن شوائبه التي تترسب في القاع، وفي الطلاء تكوين طبقة رقيقة ناعمة ومتساوية من الفضة على الجسم.', '["الشبه: تأكسد فلز الأنود واختزال أيوناته على الكاثود","الشبه: الحاجة إلى مصدر طاقة","الاختلاف في الأنود","الاختلاف في الكاثود","الاختلاف في الهدف"]'::jsonb, '[]'::jsonb, '[{"element":"أوجه الشبه مع المعادلات","marks":2},{"element":"الاختلاف في الأنود والكاثود","marks":2},{"element":"الاختلاف في الهدف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل صحيح كامل لأوجه الشبه والاختلاف بالمعادلات"},{"level":"3 درجات","description":"تحليل صحيح لأوجه الاختلاف مع نقص في الشبه أو المعادلات"},{"level":"1 درجة","description":"ذكر وجه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأنود في الطلاء غير نقي","إغفال اختلاف الهدف","كتابة Cu → Cu⁺ + e⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:23:22.596Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
